-- AlterTable
ALTER TABLE "shops" ADD COLUMN     "photo_key" TEXT,
ADD COLUMN     "photo_updated_at" TIMESTAMPTZ(3);

-- ---------------------------------------------------------------------------
-- Hand-written additions (SHP-004). Keep in sync with src/shops/shop-photo.service.ts.
-- ---------------------------------------------------------------------------

-- The key is generated by the API: shops/<shop id>/photo/<uuid>. Key and time are set together.
ALTER TABLE "shops" ADD CONSTRAINT "shops_photo_check" CHECK (
  num_nonnulls("photo_key", "photo_updated_at") IN (0, 2) AND
  ("photo_key" IS NULL OR "photo_key" ~ ('^shops/' || "id"::text || '/photo/[0-9a-f-]{36}$'))
);
